// cloud/propImages/index.js —— 道具图片 HTTP 服务（MP 后台批量导入道具用）
// 12 张 200x200 星座道具图内嵌为 base64，按 ?name=zodiac_<key> 返回 PNG。
// 响应带 Access-Control-Allow-Origin: https://mp.weixin.qq.com（微信批量导入解析图片的硬性要求）。
const IMAGES = {"zodiac_aries":"","zodiac_taurus":"","zodiac_gemini":"","zodiac_cancer":"","zodiac_leo":"","zodiac_virgo":"","zodiac_libra":"","zodiac_scorpio":"","zodiac_sagittarius":"","zodiac_capricorn":"","zodiac_aquarius":"","zodiac_pisces":""};

exports.main = async function (event) {
  const method = (event.httpMethod || event.method || 'GET').toUpperCase();

  // 预检
  if (method === 'OPTIONS') {
    return {
      statusCode: 204,
      headers: {
        'Access-Control-Allow-Origin': 'https://mp.weixin.qq.com',
        'Access-Control-Allow-Methods': 'GET,HEAD,OPTIONS',
        'Access-Control-Allow-Headers': '*'
      },
      body: ''
    };
  }

  const q = event.queryStringParameters || event.query || {};
  let name = q.name || '';
  // 兼容 /propImages/zodiac_aries 这种子路径形式
  if (!name && typeof event.path === 'string') {
    const m = event.path.match(/(zodiac_[a-z]+)/i);
    if (m) name = m[1];
  }
  const b64 = IMAGES[name];

  if (!b64) {
    return {
      statusCode: 404,
      headers: {
        'Content-Type': 'application/json;charset=utf-8',
        'Access-Control-Allow-Origin': 'https://mp.weixin.qq.com'
      },
      body: JSON.stringify({ ok: false, error: 'unknown name', available: Object.keys(IMAGES) })
    };
  }

  return {
    statusCode: 200,
    headers: {
      'Content-Type': 'image/png',
      'Content-Length': String(Buffer.byteLength(b64, 'base64')),
      'Cache-Control': 'public, max-age=86400',
      'Access-Control-Allow-Origin': 'https://mp.weixin.qq.com'
    },
    isBase64Encoded: true,
    body: b64
  };
};
